-- Rollback 00278 — retire les constats personnalisés ISO et restaure le générique 00272.
delete from public.finding_templates ft
using public.controls c, (values
  ('A.5.1', 'Aucune politique de sécurité de l''information n''existe ou celle-ci n''a jamais été approuvée par la direction, privant le SMSI de tout cadre directeur.', ARRAY['Pilotage de la sécurité inexistant et décisions non cohérentes.','Impossibilité d''opposer des règles aux collaborateurs et prestataires.','Non-conformité aux exigences de certification.'], ARRAY['Élaborer et faire valider sans délai une politique générale de sécurité par la direction.','Diffuser la politique et recueillir l''accusé de lecture de chaque collaborateur.','Planifier une revue annuelle documentée.']),
  ('A.5.12', 'Aucun schéma de classification des informations n''est défini : les données sensibles ne sont ni identifiées ni protégées selon leur criticité.', ARRAY['Données critiques traitées sans mesures de protection proportionnées.','Fuite de données confidentielles ou personnelles.','Impossibilité de dimensionner les contrôles.'], ARRAY['Établir en urgence une politique de classification (niveaux, propriétaires, règles de traitement).','Classifier en priorité les actifs informationnels critiques.','Sensibiliser l''ensemble du personnel.']),
  ('A.5.15', 'Aucune politique de contrôle d''accès n''est établie : les accès physiques et logiques sont accordés sans règle formelle ni principe du moindre privilège.', ARRAY['Accès non autorisé aux systèmes et données critiques.','Compromission de la confidentialité et de l''intégrité.','Absence de traçabilité des accès.'], ARRAY['Rédiger et déployer immédiatement une politique de contrôle d''accès.','Revoir les accès existants et retirer les droits excessifs.','Mettre en place une revue périodique des accès.']),
  ('A.5.18', 'Les droits d''accès sont attribués sans approbation ni traçabilité et ne sont pas révoqués au départ ou à la mutation, y compris sur les systèmes critiques.', ARRAY['Accès persistants d''anciens collaborateurs aux systèmes sensibles.','Abus de privilèges non détectés.','Atteinte à la confidentialité des données.'], ARRAY['Révoquer immédiatement les droits obsolètes après revue exhaustive.','Mettre en place un processus formel d''attribution et de retrait des droits.','Auditer régulièrement les comptes à privilèges.']),
  ('A.5.19', 'Aucune exigence de sécurité n''est imposée aux fournisseurs accédant aux informations ou aux systèmes, y compris les prestataires critiques.', ARRAY['Compromission via un prestataire non maîtrisé.','Fuite de données confiées à des tiers.','Responsabilité de l''organisme engagée sans recours.'], ARRAY['Cartographier les fournisseurs et classer leur criticité.','Imposer des exigences de sécurité minimales aux critiques.','Évaluer ces fournisseurs sans délai.']),
  ('A.5.20', 'Les contrats des fournisseurs critiques ne contiennent aucune clause de sécurité, de confidentialité ni de notification d''incident.', ARRAY['Aucune obligation contractuelle de protéger les données traitées.','Incident non notifié et non traçable.','Impossibilité d''auditer le fournisseur.'], ARRAY['Renégocier en priorité les contrats des fournisseurs critiques.','Intégrer des clauses de confidentialité, notification et audit.']),
  ('A.5.24', 'Aucun processus de gestion des incidents de sécurité n''est établi : ni procédure, ni responsables, ni canal de signalement.', ARRAY['Incidents non détectés ou traités tardivement avec impact amplifié.','Pas de notification aux autorités ni aux personnes concernées.','Aucune capitalisation possible.'], ARRAY['Créer sans délai une procédure de gestion des incidents et une cellule de réponse.','Mettre en place un point de contact unique de signalement.','Tester le dispositif par un exercice.']),
  ('A.5.26', 'Il n''existe aucune procédure de réponse aux incidents, les équipes réagissant de manière improvisée lors des événements de sécurité.', ARRAY['Impact prolongé sur l''activité et les données.','Perte de preuves et d''éléments d''analyse.','Manquement aux obligations de notification.'], ARRAY['Établir immédiatement des procédures de réponse et un plan de communication de crise.','Désigner et former l''équipe de réponse.','Réaliser un exercice annuel.']),
  ('A.5.29', 'Aucune disposition ne garantit le maintien de la sécurité de l''information en situation de crise ou de perturbation majeure.', ARRAY['Compromission de données lors des modes dégradés.','Impossibilité d''assurer les exigences de sécurité pendant la reprise.','Impact grave sur la continuité d''activité.'], ARRAY['Élaborer sans délai un plan intégrant la sécurité à la gestion de crise.','Définir les exigences minimales par scénario.','Effectuer un exercice de crise.']),
  ('A.5.30', 'Aucun plan de continuité informatique ni objectif de reprise n''existe pour les systèmes critiques, et aucune sauvegarde de reprise n''a été testée.', ARRAY['Arrêt prolongé de l''activité en cas de sinistre.','Perte définitive de données critiques.','Pertes financières et atteinte à la réputation.'], ARRAY['Élaborer un plan de continuité et de reprise informatique pour les systèmes critiques.','Mettre en place un site ou une solution de secours.','Tester les restaurations et documenter les résultats.']),
  ('A.5.31', 'Aucune identification des exigences légales et réglementaires applicables (données personnelles, secteur, cybersécurité) n''a été réalisée.', ARRAY['Sanctions administratives et pénales.','Perte d''agréments ou de marchés.','Responsabilité des dirigeants engagée.'], ARRAY['Réaliser rapidement un recensement des obligations légales avec un conseil juridique.','Désigner un responsable de la veille et de la conformité.','Établir un plan de mise en conformité.']),
  ('A.5.34', 'Aucun dispositif de protection des données personnelles n''est en place : pas de registre, de désignation d''un responsable ni de procédure de notification des violations.', ARRAY['Sanctions et amendes de l''autorité de protection des données.','Atteinte grave à la vie privée des personnes concernées.','Perte de confiance des clients et partenaires.'], ARRAY['Désigner un responsable de la protection des données et établir le registre des traitements.','Mettre en place les procédures de droits des personnes et de notification des violations.','Réaliser des analyses d''impact pour les traitements sensibles.']),
  ('A.7.2', 'Aucun contrôle d''accès physique ne restreint l''entrée des zones sécurisées.', ARRAY['Intrusion dans les salles hébergeant systèmes et données sensibles.','Vol ou sabotage de matériel sans traçabilité.'], ARRAY['Mettre en place un contrôle d''accès nominatif (badge).','Tenir un registre d''accès et le revoir.']),
  ('A.8.2', 'Les comptes à privilèges sont partagés ou permanents, sans inventaire, sans autorisation formelle ni revue ; des comptes d''administration génériques sont utilisés au quotidien.', ARRAY['Compromission totale du SI via un compte administrateur.','Perte d''imputabilité des actions d''administration.','Abus de privilèges non détecté.'], ARRAY['Inventorier les comptes à privilèges et supprimer les comptes partagés.','Mettre en place une gestion des accès privilégiés (PAM) avec accès temporaire.','Réaliser une revue trimestrielle des droits privilégiés.']),
  ('A.8.3', 'Les informations sensibles sont accessibles à des utilisateurs sans besoin d''en connaître (partages ouverts, droits hérités non maîtrisés) et aucun contrôle d''accès par classification n''est appliqué.', ARRAY['Divulgation d''informations confidentielles.','Fuite de données par des utilisateurs internes.','Non-conformité aux exigences contractuelles et réglementaires.'], ARRAY['Mettre en œuvre un contrôle d''accès basé sur les rôles et la classification.','Restreindre les partages ouverts et revoir les droits hérités.','Mettre en place une recertification périodique des accès.']),
  ('A.8.5', 'L''authentification multifacteur n''est pas déployée pour les accès distants, les comptes administrateurs et les applications critiques ; les mots de passe faibles sont acceptés.', ARRAY['Usurpation de compte par hameçonnage ou force brute.','Accès non autorisé aux systèmes critiques.','Compromission à grande échelle depuis un compte unique.'], ARRAY['Déployer le MFA sur les accès distants et privilégiés.','Renforcer la politique de mots de passe et bloquer les mots de passe compromis.','Mettre en place une authentification unique (SSO) sécurisée.']),
  ('A.8.7', 'Aucune solution anti-malware centralisée n''est déployée sur les postes et serveurs ; les signatures ne sont pas mises à jour et les analyses ne sont pas supervisées.', ARRAY['Infection par rançongiciel.','Propagation massive sur le réseau.','Indisponibilité prolongée des services.'], ARRAY['Déployer un antivirus/EDR centralisé sur tous les postes et serveurs.','Superviser les alertes et automatiser les mises à jour.','Définir une procédure de réponse aux infections.']),
  ('A.8.8', 'Aucun scan de vulnérabilités n''est réalisé et les correctifs de sécurité ne sont pas appliqués dans des délais maîtrisés ; des systèmes exposés fonctionnent avec des versions vulnérables.', ARRAY['Compromission via une vulnérabilité publiquement connue.','Exploitation à distance des systèmes exposés.','Interruption d''activité suite à un incident.'], ARRAY['Réaliser des scans de vulnérabilités périodiques.','Appliquer les correctifs critiques sous délai défini.','Remplacer ou isoler les systèmes en fin de support.']),
  ('A.8.13', 'Les sauvegardes des systèmes et données critiques ne sont ni planifiées ni testées, et aucune copie n''est conservée hors site ou hors ligne.', ARRAY['Perte définitive de données critiques.','Indisponibilité prolongée après un sinistre ou un rançongiciel.','Incapacité de respecter les engagements de reprise.'], ARRAY['Mettre en œuvre des sauvegardes automatisées avec copie hors site ou immuable.','Tester la restauration au moins annuellement.','Définir les objectifs RPO/RTO par système.']),
  ('A.8.15', 'Les activités des comptes à privilèges et les événements de sécurité ne sont pas journalisés ; aucune trace ne permet d''imputer les opérations d''administration.', ARRAY['Perte d''imputabilité.','Non-détection d''un incident interne.','Investigation impossible.'], ARRAY['Activer la journalisation des actions privilégiées.','Protéger les journaux contre l''altération.','Mettre en place une revue périodique.']),
  ('A.8.20', 'Les réseaux ne disposent pas de protection périmétrique ni de contrôle d''accès efficaces ; des équipements réseau sont administrés avec des configurations par défaut ou des règles trop permissives.', ARRAY['Intrusion depuis Internet ou le réseau interne.','Interception du trafic.','Compromission des équipements réseau.'], ARRAY['Mettre en place un pare-feu avec règles restrictives.','Sécuriser l''administration des équipements réseau.','Contrôler l''accès au réseau interne.']),
  ('A.8.22', 'Le réseau est à plat : aucune DMZ ni VLAN ne sépare les serveurs exposés, les postes utilisateurs et les systèmes critiques.', ARRAY['Compromission généralisée à partir d''un seul poste ou serveur.','Accès direct aux systèmes critiques depuis le réseau utilisateur.','Propagation rapide d''un rançongiciel.'], ARRAY['Créer une DMZ et des VLAN dédiés (serveurs, utilisateurs, administration).','Filtrer les flux entre zones par pare-feu.','Isoler les systèmes critiques.']),
  ('A.8.24', 'Les données sensibles ne sont pas chiffrées en transit ni au repos (protocoles non sécurisés, bases et postes non chiffrés) et les clés ne sont pas gérées.', ARRAY['Interception ou lecture de données confidentielles.','Fuite de données en clair en cas de vol ou d''intrusion.','Non-conformité réglementaire.'], ARRAY['Imposer TLS à jour pour tous les flux et chiffrer les données sensibles au repos.','Mettre en place une gestion sécurisée des clés.','Supprimer les protocoles non chiffrés.'])
) as t(code, descr, risks, recos)
where ft.control_id = c.id and c.code = t.code and ft.scope = 'platform'
  and ft.classification = 'major_nc' and ft.description = t.descr
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000010');

delete from public.finding_templates ft
using public.controls c, (values
  ('A.5.1', 'Les politiques de sécurité de l''information ne sont pas formalisées, approuvées ou communiquées à l''ensemble du personnel.', ARRAY['Absence de cadre de référence pour les décisions de sécurité.','Responsabilités SSI non opposables.'], ARRAY['Rédiger et faire approuver une politique de sécurité par la direction.','La communiquer et la revoir à intervalles planifiés.']),
  ('A.5.2', 'Les rôles et responsabilités en matière de sécurité de l''information sont partiellement définis et ne sont pas formellement attribués ni documentés.', ARRAY['Zones de responsabilité non couvertes lors d''un incident.','Redevabilité SSI floue entre métiers et DSI.'], ARRAY['Formaliser une matrice RACI des rôles SSI.','Nommer officiellement un RSSI et des relais métiers.']),
  ('A.5.3', 'Les tâches et domaines de responsabilité conflictuels ne sont pas systématiquement séparés, certains agents cumulant des fonctions incompatibles.', ARRAY['Fraude ou erreur non détectée par absence de contre-pouvoir.','Abus de privilèges sur les systèmes critiques.'], ARRAY['Cartographier les incompatibilités de fonctions.','Mettre en place des contrôles compensatoires (double validation, journalisation) là où la séparation est impossible.']),
  ('A.5.4', 'La direction n''exige pas formellement l''application de la politique de sécurité par le personnel et les prestataires, et son implication reste ponctuelle.', ARRAY['Faible appropriation des règles par les équipes.','Dérogations non maîtrisées aux règles de sécurité.'], ARRAY['Inscrire l''application de la politique SSI dans les engagements et objectifs des managers.','Organiser des revues de direction régulières du SMSI.']),
  ('A.5.5', 'Aucune liste à jour des autorités compétentes (CERT, régulateur, forces de l''ordre, autorité de protection des données) ni procédure de contact n''est établie.', ARRAY['Retard de notification en cas d''incident majeur.','Sanctions réglementaires pour déclaration tardive.'], ARRAY['Établir un annuaire des autorités avec points de contact et cas de saisine.','Définir qui est habilité à les contacter.']),
  ('A.5.6', 'L''organisme n''entretient pas de contact avec des groupes d''intérêt, forums ou associations spécialisés en sécurité de l''information.', ARRAY['Méconnaissance des bonnes pratiques et alertes émergentes.','Réponse tardive aux nouvelles vulnérabilités.'], ARRAY['Adhérer à un forum ou CERT sectoriel et désigner un référent.','Intégrer les alertes reçues dans le processus de veille.']),
  ('A.5.7', 'Il n''existe pas de processus de collecte et d''analyse des renseignements sur les menaces, la veille étant ad hoc et non exploitée.', ARRAY['Exposition à des menaces connues non anticipées.','Contrôles non adaptés au paysage de menaces actuel.'], ARRAY['Mettre en place une veille structurée (CERT, éditeurs, flux CTI).','Analyser et intégrer les menaces pertinentes dans l''appréciation des risques.']),
  ('A.5.8', 'La sécurité de l''information n''est pas intégrée de façon systématique dans la gestion de projet, sans analyse de risques ni exigences SSI en phase de cadrage.', ARRAY['Vulnérabilités introduites dès la conception des projets.','Coûts élevés de correction en fin de projet.'], ARRAY['Intégrer une analyse de risques SSI et des jalons de sécurité dans la méthodologie projet.','Désigner un référent sécurité par projet.']),
  ('A.5.9', 'L''inventaire des informations et actifs associés est incomplet, non à jour ou sans propriétaire désigné pour chaque actif.', ARRAY['Actifs non protégés car non identifiés.','Appréciation des risques incomplète.'], ARRAY['Constituer un inventaire exhaustif avec propriétaire par actif.','Le mettre à jour périodiquement et lors de chaque changement.']),
  ('A.5.10', 'Les règles d''utilisation acceptable des informations et actifs ne sont pas documentées ni acceptées par les utilisateurs.', ARRAY['Usages abusifs ou à risque des équipements et données.','Difficulté à sanctionner les manquements.'], ARRAY['Rédiger une charte d''utilisation acceptable.','La faire signer lors de l''embauche et à chaque mise à jour.']),
  ('A.5.11', 'Il n''existe pas de procédure formelle de restitution des actifs lors du départ ou du changement de poste, sans suivi de la récupération.', ARRAY['Conservation d''équipements ou de données par d''anciens collaborateurs.','Fuite d''informations après départ.'], ARRAY['Instaurer une checklist de départ incluant la restitution et son suivi.','Rapprocher le registre des actifs affectés des départs RH.']),
  ('A.5.12', 'Les informations ne sont pas classifiées selon leur criticité, ou le schéma de classification n''est pas appliqué de manière cohérente.', ARRAY['Protection inadaptée de l''information sensible.','Divulgation involontaire de données confidentielles.'], ARRAY['Définir un schéma de classification avec niveaux et critères.','Classifier les informations et former les utilisateurs.']),
  ('A.5.13', 'Les procédures de marquage des informations ne sont pas définies ou appliquées, les documents ne portant pas leur niveau de classification.', ARRAY['Manipulation inappropriée de documents sensibles.','Partage externe sans précaution.'], ARRAY['Définir des règles de marquage alignées sur la classification.','Intégrer le marquage dans les modèles de documents.']),
  ('A.5.14', 'Les règles et procédures de transfert sécurisé de l''information (messagerie, supports, tiers) ne sont pas formalisées, et des échanges sensibles s''effectuent sans chiffrement.', ARRAY['Interception ou fuite lors des échanges externes.','Envoi erroné de données confidentielles.'], ARRAY['Définir des règles de transfert par niveau de classification.','Déployer des canaux sécurisés (chiffrement, partage contrôlé).']),
  ('A.5.15', 'La politique de contrôle d''accès physique et logique est incomplète ou non appliquée uniformément selon les besoins métier.', ARRAY['Accès excessifs aux informations sensibles.','Difficulté de justifier les accès accordés.'], ARRAY['Formaliser une politique de contrôle d''accès fondée sur le besoin d''en connaître.','Appliquer et auditer sa mise en œuvre.']),
  ('A.5.16', 'Le cycle de vie des identités (création, modification, suppression) n''est pas géré de façon formalisée, avec des comptes orphelins ou génériques.', ARRAY['Comptes d''anciens agents encore actifs.','Imputabilité des actions impossible.'], ARRAY['Formaliser le processus d''arrivée, mutation et départ lié aux RH.','Supprimer les comptes orphelins et interdire les comptes partagés.']),
  ('A.5.17', 'La gestion des informations d''authentification n''est pas encadrée : règles de complexité absentes, mots de passe par défaut non changés ou partagés.', ARRAY['Compromission de comptes par force brute ou réutilisation.','Usurpation d''identité.'], ARRAY['Définir une politique de mots de passe et déployer l''authentification multifacteur.','Imposer le changement des secrets par défaut et interdire leur partage.']),
  ('A.5.18', 'L''attribution, la revue et la révocation des droits d''accès ne suivent pas de processus formel, et les revues périodiques ne sont pas réalisées.', ARRAY['Accumulation de droits injustifiés.','Droits maintenus après changement de poste.'], ARRAY['Instaurer un workflow d''approbation des demandes d''accès.','Réaliser des revues semestrielles des droits.']),
  ('A.5.19', 'Les exigences de sécurité envers les fournisseurs ne sont pas définies ni formalisées dans un processus de sélection et de suivi.', ARRAY['Recours à des fournisseurs sans garanties de sécurité.','Risques tiers non identifiés.'], ARRAY['Définir une politique de sécurité fournisseurs.','Évaluer le niveau de sécurité avant contractualisation.']),
  ('A.5.20', 'Les contrats avec les fournisseurs ne comportent pas de clauses de sécurité adaptées (confidentialité, notification d''incident, droit d''audit).', ARRAY['Absence de recours en cas d''incident chez le fournisseur.','Obligations de sécurité non opposables.'], ARRAY['Établir un socle de clauses SSI types.','Les intégrer aux contrats nouveaux et lors des renouvellements.']),
  ('A.5.21', 'La sécurité de la chaîne d''approvisionnement TIC n''est pas prise en compte : dépendances logicielles et matérielles non évaluées ni suivies.', ARRAY['Introduction de composants vulnérables ou compromis.','Dépendance non maîtrisée à des sous-traitants.'], ARRAY['Définir des exigences de sécurité pour l''achat de produits et services TIC.','Suivre les sous-traitants de rang 2 des fournisseurs critiques.']),
  ('A.5.22', 'Les prestations et changements des services fournisseurs ne font pas l''objet d''un suivi ni de revues périodiques de conformité aux exigences de sécurité.', ARRAY['Dégradation du niveau de sécurité non détectée.','Changements chez le fournisseur non évalués.'], ARRAY['Planifier des revues de performance et de sécurité des fournisseurs.','Exiger l''information préalable sur les changements significatifs.']),
  ('A.5.23', 'Les services cloud sont utilisés sans processus d''acquisition, d''évaluation ni de définition des responsabilités partagées.', ARRAY['Données hébergées sans garanties de sécurité ni de localisation.','Shadow IT cloud hors contrôle.'], ARRAY['Définir une politique d''usage des services cloud.','Évaluer chaque fournisseur cloud et documenter les responsabilités partagées.']),
  ('A.5.24', 'Le processus de gestion des incidents de sécurité est partiellement défini, sans rôles, canaux de signalement ni procédures complètes.', ARRAY['Réponse désordonnée aux incidents.','Incidents non remontés.'], ARRAY['Formaliser la procédure de gestion des incidents et les rôles.','Communiquer le canal de signalement à tout le personnel.']),
  ('A.5.25', 'Les événements de sécurité ne sont pas évalués ni catégorisés selon des critères définis, rendant la distinction événement/incident aléatoire.', ARRAY['Incidents graves sous-estimés.','Mobilisation inutile pour de faux positifs.'], ARRAY['Définir une grille de qualification et de priorisation.','Former les équipes opérationnelles à son usage.']),
  ('A.5.26', 'Les procédures de réponse aux incidents sont incomplètes ou non documentées, sans étapes de confinement, d''éradication et de reprise.', ARRAY['Propagation de l''incident faute de confinement rapide.','Temps de rétablissement allongé.'], ARRAY['Rédiger des playbooks par type d''incident.','Tester les procédures par des simulations.']),
  ('A.5.27', 'Aucun retour d''expérience n''est mené après les incidents de sécurité, et les enseignements ne sont ni documentés ni exploités.', ARRAY['Répétition des mêmes incidents.','Contrôles non améliorés.'], ARRAY['Instaurer une revue post-incident systématique.','Suivre les actions correctives décidées.']),
  ('A.5.28', 'Les procédures de collecte et de préservation des preuves numériques ne sont pas définies, sans chaîne de traçabilité.', ARRAY['Preuves inexploitables en cas de litige.','Impossibilité d''engager des poursuites.'], ARRAY['Définir une procédure de collecte et de conservation des preuves.','Former les intervenants à la préservation de la chaîne de custody.']),
  ('A.5.29', 'Le maintien de la sécurité de l''information en cas de perturbation n''est pas planifié : contrôles dégradés non identifiés en mode crise.', ARRAY['Affaiblissement des protections pendant une crise.','Exposition accrue lors des bascules de secours.'], ARRAY['Identifier les contrôles à maintenir en situation dégradée.','Les intégrer dans les plans de continuité et les tester.']),
  ('A.5.30', 'La préparation des TIC à la continuité d''activité est insuffisante : objectifs de reprise (RTO/RPO) non définis ou plans non testés.', ARRAY['Indisponibilité prolongée des systèmes critiques.','Pertes de données au-delà du tolérable.'], ARRAY['Définir les RTO/RPO par système critique.','Tester les plans de reprise au moins annuellement.']),
  ('A.5.31', 'Les exigences légales, réglementaires et contractuelles applicables ne sont pas identifiées ni tenues à jour dans un registre.', ARRAY['Non-respect involontaire de textes applicables.','Sanctions et litiges.'], ARRAY['Établir un registre des exigences applicables avec responsable.','Mettre en place une veille juridique.']),
  ('A.5.32', 'Aucune procédure ne protège les droits de propriété intellectuelle : licences logicielles non inventoriées et usage non contrôlé.', ARRAY['Poursuites pour logiciels sans licence.','Perte de maîtrise des actifs immatériels.'], ARRAY['Inventorier les licences et vérifier la conformité d''usage.','Interdire l''installation de logiciels non autorisés.']),
  ('A.5.33', 'Les enregistrements ne sont pas protégés contre la perte, la falsification ni la destruction, et les durées de conservation ne sont pas définies.', ARRAY['Perte de preuves de conformité.','Non-respect des durées légales de conservation.'], ARRAY['Définir un calendrier de conservation et des règles de protection.','Sécuriser le stockage des enregistrements critiques.']),
  ('A.5.34', 'La protection des données à caractère personnel est partiellement mise en œuvre : registre des traitements incomplet et droits des personnes mal encadrés.', ARRAY['Sanction de l''autorité de protection des données.','Atteinte aux droits des personnes concernées.'], ARRAY['Compléter le registre des traitements.','Définir les procédures d''exercice des droits et de gestion des violations.']),
  ('A.5.35', 'Aucune revue indépendante de la sécurité de l''information n''est réalisée à intervalles planifiés ni lors de changements significatifs.', ARRAY['Défaillances non détectées en l''absence de regard externe.','Fausse assurance sur l''efficacité du SMSI.'], ARRAY['Planifier des audits indépendants annuels.','Suivre les actions correctives issues des audits.']),
  ('A.5.36', 'La conformité aux politiques, règles et normes de sécurité n''est pas vérifiée régulièrement par les responsables, sans suivi des écarts.', ARRAY['Dérives non détectées par rapport aux politiques.','Écarts récurrents non corrigés.'], ARRAY['Mettre en place des contrôles de conformité périodiques par les managers.','Consigner les écarts et suivre leur résolution.']),
  ('A.5.37', 'Les procédures d''exploitation ne sont pas documentées ou accessibles, les opérations reposant sur la connaissance individuelle des équipes.', ARRAY['Erreurs d''exploitation et opérations non reproductibles.','Dépendance critique à certaines personnes.'], ARRAY['Documenter les procédures d''exploitation des systèmes.','Les mettre à disposition des intervenants et les maintenir à jour.']),
  ('A.6.1', 'Les vérifications des antécédents (identité, diplômes, références) ne sont pas systématiquement réalisées avant l''embauche.', ARRAY['Recrutement de personnes aux profils non conformes ou malveillants.','Accès à des informations sensibles par un collaborateur non vérifié.'], ARRAY['Formaliser une procédure de vérification proportionnée au niveau de sensibilité du poste.','Conserver les preuves de vérification dans le dossier du collaborateur.']),
  ('A.6.2', 'Les contrats de travail ne comportent pas de clauses précisant les responsabilités du personnel en matière de sécurité de l''information.', ARRAY['Difficulté à sanctionner ou opposer au salarié un manquement de sécurité.','Méconnaissance par le personnel de ses obligations.'], ARRAY['Intégrer une clause de sécurité de l''information dans les contrats et avenants.','Faire signer la charte de sécurité à l''embauche.']),
  ('A.6.3', 'Aucun programme périodique de sensibilisation et de formation à la sécurité de l''information n''est déployé auprès de l''ensemble du personnel.', ARRAY['Succès des attaques d''hameçonnage et d''ingénierie sociale.','Comportements à risque et non-respect des politiques.'], ARRAY['Établir un plan annuel de sensibilisation avec évaluation des acquis.','Former les nouveaux arrivants dès leur intégration et tracer les participations.']),
  ('A.6.4', 'Aucun processus disciplinaire formalisé ne définit les sanctions applicables en cas de violation de la politique de sécurité.', ARRAY['Absence d''effet dissuasif face aux manquements.','Contestation des sanctions faute de cadre établi.'], ARRAY['Formaliser et communiquer un processus disciplinaire lié à la sécurité.','Valider ce processus avec les RH et le juridique.']),
  ('A.6.5', 'Les responsabilités et obligations de sécurité restant valables après la fin ou le changement d''emploi ne sont ni définies ni communiquées.', ARRAY['Divulgation d''informations par d''anciens collaborateurs.','Conservation d''accès ou d''actifs après le départ.'], ARRAY['Définir les obligations post-emploi et les rappeler lors de l''entretien de départ.','Mettre en place une checklist de départ (accès, matériel, rappel de confidentialité).']),
  ('A.6.6', 'Les accords de confidentialité ou de non-divulgation ne sont pas systématiquement signés par le personnel et les tiers.', ARRAY['Fuite d''informations confidentielles sans recours juridique.','Divulgation par des prestataires non engagés.'], ARRAY['Utiliser un modèle d''accord de confidentialité signé par tout collaborateur et tiers.','Revoir périodiquement les accords et tenir un registre des signatures.']),
  ('A.6.7', 'Aucune politique de sécurité du télétravail n''encadre l''accès distant, les équipements et les environnements de travail hors site.', ARRAY['Compromission de données via des réseaux domestiques non sécurisés.','Perte ou vol d''équipements et d''informations hors des locaux.'], ARRAY['Rédiger une politique de télétravail imposant VPN, chiffrement et authentification forte.','Sensibiliser les télétravailleurs aux règles de confidentialité à domicile.']),
  ('A.6.8', 'Aucun mécanisme formalisé ne permet au personnel de signaler rapidement les événements de sécurité observés ou suspectés.', ARRAY['Détection tardive des incidents.','Aggravation des impacts faute de remontée d''information.'], ARRAY['Mettre en place un canal unique de signalement (adresse, formulaire, téléphone).','Communiquer la procédure et en tester l''usage.']),
  ('A.7.1', 'Les périmètres de sécurité physique ne sont pas définis et les zones contenant des informations ou actifs sensibles ne sont pas délimitées.', ARRAY['Accès non autorisé aux zones sensibles.','Niveau de protection inadapté aux actifs hébergés.'], ARRAY['Définir et documenter les zones de sécurité selon la sensibilité des actifs.','Matérialiser les périmètres par des barrières physiques adaptées.']),
  ('A.7.2', 'Aucun contrôle d''accès physique ne restreint l''entrée des zones sécurisées.', ARRAY['Intrusion dans les salles hébergeant systèmes et données sensibles.','Vol ou sabotage de matériel sans traçabilité.'], ARRAY['Mettre en place un contrôle d''accès nominatif (badge).','Tenir un registre d''accès et le revoir.']),
  ('A.7.3', 'Les bureaux, salles et équipements ne disposent pas de protections physiques adaptées (verrouillage, accès restreint).', ARRAY['Accès non autorisé à des informations ou équipements.','Vol de matériel ou de documents.'], ARRAY['Verrouiller les locaux et armoires contenant des informations sensibles.','Gérer et tracer la distribution des clés et badges.']),
  ('A.7.4', 'Les locaux ne font pas l''objet d''une surveillance continue (vidéosurveillance, alarme) permettant de détecter les accès non autorisés.', ARRAY['Intrusions non détectées.','Absence de preuves en cas d''incident.'], ARRAY['Déployer vidéosurveillance et alarme intrusion sur les zones sensibles.','Définir durée de conservation des enregistrements et procédure de revue.']),
  ('A.7.5', 'Les protections contre les menaces physiques et environnementales (incendie, inondation, surtension) sont absentes ou insuffisantes.', ARRAY['Destruction d''équipements et de données.','Interruption prolongée des services.'], ARRAY['Installer détection et extinction incendie ainsi que protections contre l''eau.','Réaliser une analyse des menaces environnementales et la revoir.']),
  ('A.7.6', 'Aucune règle ne encadre le travail dans les zones sécurisées (présence de tiers, appareils d''enregistrement, supervision).', ARRAY['Activités non supervisées dans des zones sensibles.','Captation d''informations par des appareils non autorisés.'], ARRAY['Définir des règles de travail et d''accompagnement des visiteurs en zone sécurisée.','Interdire les appareils d''enregistrement non autorisés.']),
  ('A.7.7', 'Aucune politique de bureau propre et d''écran vide n''est appliquée ; documents et sessions restent accessibles sans surveillance.', ARRAY['Consultation d''informations par des personnes non autorisées.','Fuite de données par documents laissés visibles.'], ARRAY['Adopter une politique clean desk / clear screen avec verrouillage automatique des sessions.','Réaliser des contrôles inopinés périodiques.']),
  ('A.7.8', 'Le positionnement des équipements ne limite pas les risques liés à l''environnement et aux accès non autorisés.', ARRAY['Vol ou dégradation d''équipements.','Observation d''écrans par des personnes non habilitées.'], ARRAY['Installer les équipements critiques en zones protégées et à l''abri des risques environnementaux.','Orienter ou filtrer les écrans exposés au public.']),
  ('A.7.9', 'Les actifs utilisés hors des locaux (portables, mobiles) ne font pas l''objet de mesures de protection définies.', ARRAY['Perte ou vol de matériel contenant des données non chiffrées.','Accès non autorisé aux informations de l''entreprise.'], ARRAY['Imposer le chiffrement des disques et la gestion centralisée des terminaux mobiles.','Définir les règles d''usage et de déclaration de perte des équipements.']),
  ('A.7.10', 'La gestion des supports de stockage amovibles (clés USB, disques externes) n''est pas encadrée sur tout leur cycle de vie.', ARRAY['Fuite de données via supports perdus ou copiés.','Propagation de logiciels malveillants.'], ARRAY['Définir une procédure de gestion des supports amovibles et restreindre leur usage.','Imposer le chiffrement et tenir un inventaire des supports.']),
  ('A.7.11', 'Les services généraux (alimentation électrique, télécoms, climatisation) ne sont pas protégés contre les pannes et défaillances.', ARRAY['Indisponibilité des systèmes lors de coupures.','Dommages matériels dus aux perturbations électriques.'], ARRAY['Installer onduleurs et groupe électrogène avec tests périodiques.','Prévoir une redondance des liens télécoms et de la climatisation.']),
  ('A.7.12', 'Les câbles d''alimentation et réseau ne sont pas protégés contre l''interception, les interférences et les dommages.', ARRAY['Interception ou sabotage des communications.','Interruption de service suite à des dommages de câblage.'], ARRAY['Protéger et séparer les câblages dans des chemins sécurisés et étiquetés.','Contrôler périodiquement l''état et l''accès aux locaux techniques.']),
  ('A.7.13', 'La maintenance du matériel n''est pas planifiée ni tracée selon les préconisations des fabricants.', ARRAY['Pannes non anticipées des équipements.','Intervention de tiers non contrôlés sur des matériels sensibles.'], ARRAY['Établir un plan de maintenance préventive et conserver les rapports d''intervention.','Superviser les interventions externes et effacer les données avant sortie du matériel.']),
  ('A.7.14', 'Aucune procédure d''effacement sécurisé ne garantit la suppression des données avant mise au rebut ou réutilisation du matériel.', ARRAY['Récupération de données sensibles sur du matériel cédé ou jeté.','Fuite d''informations via des disques non effacés.'], ARRAY['Définir une procédure d''effacement ou de destruction certifiée avant mise au rebut.','Conserver les certificats de destruction et tenir un registre.']),
  ('A.8.1', 'Les postes de travail et terminaux mobiles ne sont pas systématiquement protégés (chiffrement du disque, verrouillage automatique, gestion centralisée) ; plusieurs terminaux personnels accèdent aux ressources de l''organisation sans contrôle.', ARRAY['Divulgation d''informations en cas de perte ou de vol d''un terminal.','Compromission du SI via un terminal non maîtrisé.','Fuite de données vers des appareils personnels.'], ARRAY['Imposer le chiffrement des disques et le verrouillage automatique des terminaux.','Déployer une solution de gestion centralisée des terminaux (MDM/MAM).','Formaliser une politique d''usage des terminaux personnels (BYOD).']),
  ('A.8.2', 'Les droits d''accès privilégiés sont attribués sans procédure formelle d''autorisation ni revue périodique.', ARRAY['Abus de privilèges.','Élévation de privilèges non détectée.','Comptes privilégiés orphelins.'], ARRAY['Formaliser l''attribution des droits privilégiés avec validation.','Réviser les comptes à privilèges au moins semestriellement.','Séparer les comptes d''administration des comptes courants.']),
  ('A.8.3', 'Les accès aux informations ne sont pas systématiquement limités au besoin d''en connaître ; certains droits ne sont pas documentés.', ARRAY['Accès inapproprié à des informations sensibles.','Accumulation de droits excessifs.','Difficulté à justifier les accès.'], ARRAY['Documenter une matrice des droits d''accès par rôle.','Revoir périodiquement les droits attribués.','Appliquer le principe du moindre privilège.']),
  ('A.8.4', 'L''accès en lecture et en écriture au code source et aux outils de développement n''est pas restreint ni tracé de façon formelle.', ARRAY['Modification non autorisée du code.','Vol de propriété intellectuelle.','Introduction de code malveillant.'], ARRAY['Restreindre l''accès aux dépôts selon les rôles.','Activer la traçabilité et la revue des modifications.','Protéger les branches principales par revue obligatoire.']),
  ('A.8.5', 'Les mécanismes d''authentification ne respectent pas une politique de mots de passe robuste et homogène sur l''ensemble des systèmes.', ARRAY['Compromission de comptes par force brute.','Réutilisation de mots de passe faibles.','Accès non autorisé aux applications.'], ARRAY['Définir et appliquer une politique de mots de passe.','Limiter les tentatives de connexion échouées.','Sensibiliser les utilisateurs aux bonnes pratiques.']),
  ('A.8.6', 'L''utilisation des ressources (stockage, calcul, bande passante) n''est ni surveillée ni projetée ; aucun plan de capacité n''existe.', ARRAY['Saturation des ressources et indisponibilité.','Dégradation des performances des services.','Dépenses d''urgence non maîtrisées.'], ARRAY['Surveiller l''utilisation des ressources avec des seuils d''alerte.','Établir un plan de capacité annuel.','Intégrer les besoins de capacité aux projets.']),
  ('A.8.7', 'La protection contre les programmes malveillants est incomplète ; une partie du parc n''est pas couverte ou n''est pas à jour.', ARRAY['Infection par un logiciel malveillant.','Propagation latérale.','Perte ou chiffrement de données.'], ARRAY['Étendre la protection anti-malware à l''ensemble du parc.','Automatiser les mises à jour des signatures.','Sensibiliser les utilisateurs aux pièces jointes et liens suspects.']),
  ('A.8.8', 'La veille sur les vulnérabilités techniques et l''application des correctifs ne suivent pas de processus formalisé ni de délais définis.', ARRAY['Exploitation de vulnérabilités connues.','Systèmes obsolètes non corrigés.','Absence de priorisation des correctifs.'], ARRAY['Définir un processus de gestion des correctifs avec délais par criticité.','Mettre en place une veille sur les vulnérabilités.','Tenir un inventaire des versions logicielles.']),
  ('A.8.9', 'Les configurations de sécurité des systèmes et équipements ne sont pas définies, documentées ni contrôlées par rapport à une référence.', ARRAY['Configurations par défaut vulnérables.','Dérive de configuration non détectée.','Incohérence entre systèmes.'], ARRAY['Établir des référentiels de configuration sécurisée.','Contrôler périodiquement la conformité des configurations.','Documenter et versionner les configurations.']),
  ('A.8.10', 'Aucune procédure d''effacement sécurisé n''est appliquée aux informations et supports en fin de vie ou de service.', ARRAY['Récupération de données après mise au rebut.','Conservation excessive d''informations.','Non-conformité aux exigences de protection des données.'], ARRAY['Définir une procédure d''effacement sécurisé des supports.','Appliquer les durées de conservation définies.','Conserver une preuve de destruction.']),
  ('A.8.11', 'Les données sensibles sont utilisées en clair dans les environnements non nécessaires ; aucune règle de masquage ou de pseudonymisation n''est définie.', ARRAY['Exposition de données personnelles.','Fuite via les environnements de test ou d''analyse.','Non-conformité réglementaire.'], ARRAY['Définir les règles de masquage et de pseudonymisation par type de donnée.','Appliquer le masquage dans les environnements non productifs.','Limiter l''affichage des données sensibles selon le rôle.']),
  ('A.8.12', 'Aucun dispositif de prévention de la fuite de données n''est en place ; les sorties d''informations sensibles (messagerie, supports amovibles, cloud) ne sont ni contrôlées ni surveillées.', ARRAY['Exfiltration non détectée d''informations sensibles.','Fuite via la messagerie ou le stockage cloud personnel.','Atteinte à l''image et sanctions contractuelles.'], ARRAY['Mettre en place des contrôles DLP sur messagerie, postes et cloud.','Restreindre les supports amovibles et les services de partage externes.','Sensibiliser les utilisateurs aux règles de diffusion.']),
  ('A.8.13', 'La politique de sauvegarde est partielle et les restaurations ne sont pas testées régulièrement.', ARRAY['Impossibilité de restaurer à temps.','Perte de données récentes.','Sauvegardes inexploitables.'], ARRAY['Formaliser la politique de sauvegarde (périmètre, fréquence, rétention).','Tester les restaurations périodiquement.','Superviser les résultats des sauvegardes.']),
  ('A.8.14', 'Les systèmes critiques ne disposent pas de redondance ; plusieurs composants constituent un point de défaillance unique.', ARRAY['Interruption de service lors d''une panne matérielle.','Indisponibilité prolongée des processus critiques.','Non-respect des engagements de disponibilité.'], ARRAY['Identifier les points de défaillance uniques.','Mettre en place la redondance des composants critiques.','Tester périodiquement les bascules.']),
  ('A.8.15', 'La journalisation est partielle ; certains systèmes ne produisent pas de journaux exploitables et leur conservation n''est pas définie.', ARRAY['Investigation incomplète d''un incident.','Perte d''éléments de preuve.','Détection tardive d''anomalies.'], ARRAY['Définir le périmètre et la durée de conservation des journaux.','Centraliser les journaux des systèmes critiques.','Restreindre l''accès aux journaux.']),
  ('A.8.16', 'Aucune surveillance systématique des réseaux, systèmes et applications n''est assurée ; les comportements anormaux ne sont pas détectés ni analysés.', ARRAY['Détection tardive des intrusions.','Incidents découverts par des tiers.','Allongement du temps de réponse.'], ARRAY['Définir le périmètre et les indicateurs de surveillance.','Mettre en place des alertes sur les événements anormaux.','Centraliser l''analyse via un SIEM ou un service managé.']),
  ('A.8.17', 'Les horloges des systèmes ne sont pas synchronisées sur une source de temps commune et fiable.', ARRAY['Corrélation impossible des journaux.','Contestation de la valeur probante des traces.','Dysfonctionnements d''authentification.'], ARRAY['Configurer la synchronisation NTP sur une source de référence.','Vérifier périodiquement les dérives d''horloge.','Documenter la source de temps officielle.']),
  ('A.8.18', 'L''usage des programmes utilitaires pouvant contourner les contrôles de sécurité n''est ni restreint ni journalisé.', ARRAY['Contournement des mesures de sécurité.','Modification non tracée de systèmes.','Abus par des utilisateurs non autorisés.'], ARRAY['Inventorier et restreindre les utilitaires privilégiés.','Réserver leur usage aux personnes autorisées.','Journaliser leur utilisation.']),
  ('A.8.19', 'L''installation de logiciels sur les systèmes opérationnels n''est soumise à aucune procédure d''autorisation ; des utilisateurs disposent de droits d''installation.', ARRAY['Introduction de logiciels non autorisés ou malveillants.','Incompatibilités et instabilité des systèmes.','Non-conformité des licences.'], ARRAY['Retirer les droits d''installation aux utilisateurs.','Établir une liste de logiciels autorisés.','Valider et tester toute installation avant déploiement.']),
  ('A.8.20', 'Les réseaux ne sont pas pleinement sécurisés ; l''inventaire des équipements et la gestion des règles de filtrage ne sont pas à jour.', ARRAY['Accès réseau non autorisé.','Règles de filtrage obsolètes.','Visibilité insuffisante sur les flux.'], ARRAY['Tenir à jour la cartographie réseau.','Réviser périodiquement les règles de filtrage.','Documenter les flux autorisés.']),
  ('A.8.21', 'Les exigences de sécurité et de niveau de service des services réseau fournis par des tiers ne sont pas définies ni contractualisées.', ARRAY['Indisponibilité non couverte par un engagement.','Absence de contrôle sur la sécurité des opérateurs.','Difficulté à faire valoir les droits contractuels.'], ARRAY['Inclure des exigences de sécurité et des SLA dans les contrats réseau.','Suivre les performances des fournisseurs.','Prévoir des solutions de repli.']),
  ('A.8.22', 'Le réseau est insuffisamment segmenté ; les groupes de services, utilisateurs et systèmes d''information ne sont pas séparés de façon documentée.', ARRAY['Propagation latérale d''une attaque.','Exposition de systèmes internes.','Difficulté de contrôle des flux.'], ARRAY['Définir une architecture de segmentation par criticité.','Documenter les zones et les flux inter-zones.','Contrôler les flux entre segments.']),
  ('A.8.23', 'Aucun filtrage des accès aux sites web externes n''est appliqué ; les utilisateurs peuvent consulter des sites malveillants ou inappropriés.', ARRAY['Téléchargement de logiciels malveillants.','Hameçonnage via des sites frauduleux.','Usage non professionnel de la bande passante.'], ARRAY['Déployer un filtrage web par catégories.','Bloquer les sites malveillants connus.','Journaliser les accès et revoir les exceptions.']),
  ('A.8.24', 'Aucune politique de cryptographie ne définit les algorithmes, les longueurs de clés ni la gestion du cycle de vie des clés.', ARRAY['Usage d''algorithmes obsolètes.','Perte ou compromission de clés.','Protection incohérente selon les systèmes.'], ARRAY['Rédiger une politique de cryptographie.','Définir la gestion du cycle de vie des clés.','Recenser les usages et migrer les algorithmes faibles.']),
  ('A.8.25', 'Aucun cycle de développement sécurisé n''est formalisé ; la sécurité n''est pas intégrée aux phases du développement.', ARRAY['Vulnérabilités détectées tardivement.','Coûts de correction élevés.','Pratiques hétérogènes entre projets.'], ARRAY['Formaliser un cycle de développement sécurisé.','Intégrer des jalons de sécurité dans chaque phase.','Former les équipes de développement.']),
  ('A.8.26', 'Les exigences de sécurité des applications ne sont pas identifiées ni spécifiées lors de la conception ou de l''acquisition.', ARRAY['Applications livrées sans contrôles essentiels.','Exposition des transactions et des données.','Corrections coûteuses après mise en production.'], ARRAY['Définir un catalogue d''exigences de sécurité applicative.','Les intégrer aux cahiers des charges.','Valider leur prise en compte à la recette.']),
  ('A.8.27', 'Aucun principe d''ingénierie et d''architecture sécurisées n''est défini ni appliqué aux systèmes d''information.', ARRAY['Architectures fragiles dès la conception.','Absence de défense en profondeur.','Faiblesses difficiles à corriger a posteriori.'], ARRAY['Établir des principes d''architecture sécurisée (moindre privilège, défense en profondeur).','Réaliser une revue d''architecture pour les nouveaux projets.','Documenter les décisions de sécurité.']),
  ('A.8.28', 'Aucune règle de codage sécurisé n''est définie ; les développeurs ne disposent ni de référentiel ni d''outils d''analyse de code.', ARRAY['Vulnérabilités applicatives (injection, XSS).','Dette de sécurité accumulée.','Exploitation des applications exposées.'], ARRAY['Adopter un référentiel de codage sécurisé.','Intégrer l''analyse statique de code au pipeline.','Réaliser des revues de code.']),
  ('A.8.29', 'Les tests de sécurité (revue de code, tests d''intrusion, tests d''acceptation) ne sont pas réalisés avant la mise en production.', ARRAY['Mise en production d''applications vulnérables.','Découverte des failles par des attaquants.','Absence de preuve de la sécurité livrée.'], ARRAY['Planifier des tests de sécurité avant chaque mise en production.','Réaliser un test d''intrusion annuel des applications critiques.','Suivre la correction des vulnérabilités détectées.']),
  ('A.8.30', 'Le développement externalisé n''est pas encadré par des exigences de sécurité contractuelles ni supervisé.', ARRAY['Code livré non sécurisé.','Fuite de code source ou de données.','Dépendance non maîtrisée envers le prestataire.'], ARRAY['Inclure des clauses de sécurité et de propriété du code dans les contrats.','Contrôler la qualité et la sécurité des livrables.','Auditer périodiquement les prestataires.']),
  ('A.8.31', 'Les environnements de développement, de test et de production ne sont pas séparés ; des développeurs accèdent directement à la production.', ARRAY['Altération accidentelle de la production.','Fuite de données de production.','Déploiement de code non validé.'], ARRAY['Séparer logiquement et physiquement les environnements.','Restreindre les accès à la production.','Contrôler le passage de code entre environnements.']),
  ('A.8.32', 'Les changements apportés aux systèmes ne suivent pas de processus formalisé d''évaluation, d''autorisation et de test.', ARRAY['Incidents suite à des changements non maîtrisés.','Introduction de vulnérabilités.','Absence de plan de retour arrière.'], ARRAY['Formaliser un processus de gestion des changements.','Imposer autorisation, tests et plan de retour arrière.','Tenir un registre des changements.']),
  ('A.8.33', 'Des données réelles de production sont utilisées comme données de test sans protection ni autorisation.', ARRAY['Exposition de données confidentielles.','Fuite via des environnements moins protégés.','Non-conformité en matière de protection des données.'], ARRAY['Utiliser des données fictives ou anonymisées.','Soumettre toute copie de données réelles à autorisation.','Effacer les données de test après usage.']),
  ('A.8.34', 'Les tests d''audit et contrôles techniques sur les systèmes opérationnels ne sont pas planifiés ni convenus avec la direction.', ARRAY['Interruption de services lors des tests.','Accès excessif des auditeurs.','Altération de données de production.'], ARRAY['Convenir par écrit du périmètre et des conditions des tests.','Limiter les accès des auditeurs en lecture seule.','Planifier les tests hors périodes critiques.'])
) as t(code, descr, risks, recos)
where ft.control_id = c.id and c.code = t.code and ft.scope = 'platform'
  and ft.classification = 'minor_nc' and ft.description = t.descr
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000010');

