  ('A.8.29', 'Non-conformité à la mesure A.8.29 « Tests de sécurité dans le développement et l''acceptation ».', 'Manquement à une mesure ISO 27001 (Mesures technologiques) — compromission technique du système d’information.', 'Mettre en œuvre la mesure : Tests de pénétration et revues de code'),
  ('A.8.30', 'Non-conformité à la mesure A.8.30 « Développement externalisé ».', 'Manquement à une mesure ISO 27001 (Mesures technologiques) — compromission technique du système d’information.', 'Mettre en œuvre la mesure : Sécurité du développement sous-traité'),
  ('A.8.31', 'Non-conformité à la mesure A.8.31 « Séparation des environnements de développement, de test et opérationnels ».', 'Manquement à une mesure ISO 27001 (Mesures technologiques) — compromission technique du système d’information.', 'Mettre en œuvre la mesure : Isolation dev/test/prod'),
  ('A.8.32', 'Non-conformité à la mesure A.8.32 « Gestion des changements ».', 'Manquement à une mesure ISO 27001 (Mesures technologiques) — compromission technique du système d’information.', 'Mettre en œuvre la mesure : Processus de gestion des changements'),
  ('A.8.33', 'Non-conformité à la mesure A.8.33 « Informations de test ».', 'Manquement à une mesure ISO 27001 (Mesures technologiques) — compromission technique du système d’information.', 'Mettre en œuvre la mesure : Protection des données de test'),
  ('A.8.34', 'Non-conformité à la mesure A.8.34 « Protection des systèmes d''information durant les tests d''audit ».', 'Manquement à une mesure ISO 27001 (Mesures technologiques) — compromission technique du système d’information.', 'Mettre en œuvre la mesure : Sécurité pendant les audits techniques')
) as t(code, descr, risk, reco)
join public.controls c on c.code = t.code
  and c.domain_id in (select id from public.domains where framework_id = '00000000-0000-0000-0000-000000000010')
where not exists (
  select 1 from public.finding_templates ft
  where ft.control_id = c.id and ft.scope = 'platform' and ft.classification = 'minor_nc'
);
